let backendUser=null,backendQueue=Promise.resolve(),backendSaveTimer,backendReady=false;
async function api(path,method='GET',body){const res=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CareerBridge':'1'},...(body!==undefined?{body:JSON.stringify(body)}:{})});let data;try{data=await res.json()}catch{throw Error('Server connection unavailable.')}if(!res.ok)throw Error(data.error||'Request failed.');return data}
function backendStatus(text){const el=document.getElementById('account-status');if(el)el.textContent=text}
function persistSnapshot(payload){backendStatus('Saving…');backendQueue=backendQueue.catch(()=>{}).then(()=>api('state','PUT',payload)).then(()=>backendStatus('All changes saved')).catch(e=>{backendStatus('Not saved · retry');toast(e.message);throw e});backendQueue.catch(()=>{});return backendQueue}
function queueBackendSave(){if(!backendUser){backendStatus('Sign in to save progress');return}clearTimeout(backendSaveTimer);backendSaveTimer=setTimeout(()=>persistSnapshot(JSON.parse(JSON.stringify(state))),500)}
function freshState(){return {profile:{...defaults},tasks:[],saved:[],resume:'',answers:{}}}
function accountUI(){let el=$('#account-controls');if(!el){el=document.createElement('div');el.id='account-controls';el.className='account-controls';document.body.append(el)}el.innerHTML=backendUser?`<span id="account-status" role="status">All changes saved</span><button id="account-open" class="primary">My account</button>`:`<span id="account-status" role="status">${backendReady?'Sign in to save progress':'Connecting to server…'}</span><button id="account-open" class="primary">Sign in / Register</button>`;$('#account-open').onclick=showAccount}
function showAccount(){let dialog=$('#account-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='account-dialog';dialog.className='account-dialog';document.body.append(dialog)}dialog.innerHTML=backendUser?`<button class="dialog-close" aria-label="Close account dialog">×</button><div class="eyebrow">YOUR ACCOUNT</div><h2>Welcome back.</h2><p>${esc(backendUser.email)}</p><p>Your profile, resume drafts and progress are saved to your account.</p><div class="actions"><button class="outline" id="retry-sync">Save again</button><button class="primary" id="account-logout">Sign out</button></div><p id="auth-message" role="status"></p>`:`<button class="dialog-close" aria-label="Close sign-in dialog">×</button><div class="eyebrow">KEEP YOUR MOMENTUM</div><h2>Your journey, saved.</h2><p>Sign in on any device to pick up where you left off. Creating an account saves your current workspace.</p><form id="account-auth"><label for="account-email">Email</label><input id="account-email" type="email" required maxlength="254" autocomplete="username"><label for="account-password">Password</label><input id="account-password" type="password" required minlength="10" maxlength="128" autocomplete="current-password"><small>Use 10–128 characters.</small><div class="actions"><button class="primary" value="login" name="action">Sign in</button><button class="outline" value="register" name="action">Create account</button></div><p id="auth-message" role="status"></p></form>`;dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.showModal();if(!backendUser){$('#account-auth').onsubmit=async e=>{e.preventDefault();let action=e.submitter.value;let buttons=[...e.target.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);$('#auth-message').textContent='Please wait…';try{let user=await api('auth/'+action,'POST',{email:$('#account-email').value,password:$('#account-password').value});if(action==='register')await api('state','PUT',state);const loaded=await api('state');backendUser=user;backendReady=true;state=loaded;chosenRole=null;render();accountUI();dialog.close();toast(action==='register'?'Account created. Your workspace is saved.':'Signed in. Your workspace is loaded.')}catch(err){$('#auth-message').textContent=err.message}finally{buttons.forEach(b=>b.disabled=false)}}}else{$('#retry-sync').onclick=async()=>{try{await persistSnapshot(JSON.parse(JSON.stringify(state)));$('#auth-message').textContent='All changes saved.'}catch(e){$('#auth-message').textContent=e.message}};$('#account-logout').onclick=async e=>{e.target.disabled=true;try{clearTimeout(backendSaveTimer);await backendQueue.catch(()=>{});await api('state','PUT',state);await api('auth/logout','POST',{});backendUser=null;state=freshState();chosenRole=null;render();accountUI();dialog.close();toast('Signed out.')}catch(err){$('#auth-message').textContent=err.message;e.target.disabled=false}}}}
accountUI();
(async()=>{try{await api('health');backendReady=true;try{const user=await api('auth/me');const loaded=await api('state');backendUser=user;state=loaded;render()}catch(e){if(e.message!=='Sign in to access your account.')throw e}accountUI()}catch(e){backendStatus('Server unavailable · setup required');console.error('Backend connection unavailable.')}})();
window.addEventListener('pagehide',()=>{if(backendUser){clearTimeout(backendSaveTimer);fetch('/api/state',{method:'PUT',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json','X-CareerBridge':'1'},body:JSON.stringify(state)}).catch(()=>{})}});
